import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import tailwindcss from "@tailwindcss/vite";
import { resolve } from "node:path";
import { LANGUAGES } from "./scripts/build-pages.mjs";

// Pages are generated by scripts/build-pages.mjs (run by the dev and build scripts).
const pages = ["index", "privacy", "terms", "support"];
const input = Object.fromEntries(
  LANGUAGES.flatMap((l) =>
    pages.map((p) => [`${l.slug || "en"}-${p}`, resolve(import.meta.dirname, l.slug, `${p}.html`)]),
  ),
);

export default defineConfig({
  base: "./",
  plugins: [react(), tailwindcss()],
  build: { rollupOptions: { input } },
});
